/* =========================================================
   🌙 暗黑模式：深黑顶栏 · 专属绿气泡 · 极致护眼质感版
   ========================================================= */
:root {
  /* === 全局背景与遮罩 === */
  --chat-bg-color: #111111; /* 极深灰/纯黑背景 */
  --chat-bg-overlay: rgba(0, 0, 0, 0.45); /* 🎯 半透明深灰遮罩，压暗背景图 */

  /* 顶栏基础变量 */
  --chat-header-height: 56px;

  /* 🎯🎯 主标题(备注)设置 🎯🎯 */
  --chat-header-title-color: #e0e0e0; /* 夜间模式浅色字 */
  --chat-header-title-size: 17px;
  --chat-header-title-weight: 600;
  --title-top-position: 70%; 

  /* 🎯🎯 自定义副标题设置 🎯🎯 */
  --custom-subtitle-text: ""; 
  --custom-subtitle-color: #888888; /* 中灰 */
  --custom-subtitle-size: 11px;
  --custom-subtitle-top: 22px; 

  /* 隐藏系统原生副标题和头像 */
  --chat-header-subtitle-color: transparent;
  --chat-header-subtitle-size: 0px;
  --chat-header-avatar-size: 0px;

  /* === 素净模式布局 === */
  --plain-gap-between-groups: 20px;
  --plain-gap-within-group: 6px;
  --plain-content-max-width: 65%;
  --plain-padding-left-me: 60px;
  --plain-padding-right-me: 0px;
  --plain-padding-left-them: 0px;
  --plain-padding-right-them: 60px;
  --plain-avatar-size: 42px;
  --plain-avatar-radius: 6px;
  --plain-avatar-gap: 10px;

  /* 🎯🎯 我方气泡 (指定绿 #27B465 + 黑字) 🎯🎯 */
  --bubble-me-bg: linear-gradient(to bottom, #2ec972 0%, #27B465 100%);
  --bubble-me-color: #1a1a1a; /* 🎯 黑色字 */
  --bubble-me-padding: 7px 10px;
  --bubble-me-radius: 4px;
  --bubble-me-border: 1px solid #1f9351; /* 稍深的绿色边框 */
  --bubble-me-shadow: inset 0 1px 0 rgba(255,255,255,0.2), 0 1px 2px rgba(0,0,0,0.3);

  /* 🎯🎯 对方气泡 (高级碳灰) 🎯🎯 */
  --bubble-them-bg: linear-gradient(to bottom, #2c2c2e 0%, #242426 100%);
  --bubble-them-color: #e0e0e0;
  --bubble-them-padding: 7px 10px;
  --bubble-them-radius: 4px;
  --bubble-them-border: 1px solid #3a3a3c;
  --bubble-them-shadow: inset 0 1px 0 rgba(255,255,255,0.05), 0 1px 2px rgba(0,0,0,0.3);
}

/* =========================================================
   🎯🎯 顶栏定制 (深黑渐变 + 柔和高光) 🎯🎯
   ========================================================= */
.chat-header-custom {
  /* 🎯 深黑渐变 */
  background: linear-gradient(to bottom, #1a1a1a 0%, #111111 100%) !important;
  border-bottom: 1px solid #222222 !important;
  /* 🎯 极弱的顶部高光，保持立体感但不刺眼 */
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.05) !important; 
  position: relative !important;
}

.chat-header-custom .chat-header-title {
  text-shadow: 0 1px 0 rgba(0,0,0,0.8) !important; /* 黑底黑阴影，增加厚度 */
  position: absolute !important;
  left: 50% !important;
  top: var(--title-top-position) !important; 
  transform: translate(-50%, -50%) !important;
  margin: 0 !important;
  padding: 0 !important;
  width: max-content !important;
  z-index: 10 !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  overflow: visible !important;
}

.header-avatar-container { display: none !important; }
.chat-header-subtitle { display: none !important; } 

.chat-header-custom .chat-header-title::after {
  content: var(--custom-subtitle-text) !important;
  position: absolute !important;
  top: var(--custom-subtitle-top) !important; 
  left: 50% !important;
  transform: translateX(-50%) !important;
  color: var(--custom-subtitle-color) !important;
  font-size: var(--custom-subtitle-size) !important;
  font-weight: 400 !important;
  white-space: nowrap !important;
}

.header-btn-phone, .header-btn-video { 
  opacity: 0 !important; 
  pointer-events: auto !important; 
}

.header-btn-back svg { display: none !important; }
.header-btn-back::after {
  content: "" !important;
  position: absolute !important;
  left: 16px !important;
  width: 24px !important; 
  height: 24px !important;
  /* 图标换成浅灰 %23e0e0e0 */
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23e0e0e0' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><polyline points='15 18 9 12 15 6'/></svg>") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
}

.header-btn-info svg { display: none !important; }
.header-btn-info {
  position: relative !important;
  width: 32px !important;
  height: 32px !important;
}
.header-btn-info::after {
  content: "" !important;
  position: absolute !important;
  inset: 0 !important;
  /* 图标换成浅灰 %23e0e0e0 */
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='%23e0e0e0'><circle cx='5' cy='12' r='2'/><circle cx='12' cy='12' r='2'/><circle cx='19' cy='12' r='2'/></svg>") !important;
  background-size: 24px !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
}

/* ===== 仿微信底栏 (夜间深黑立体质感版) ===== */
