.input-box-custom::placeholder { color: transparent !important; }

/* 按钮组透明，落在白框外 */
.input-btns-right {
    background: transparent !important;
    background-color: transparent !important;
}

/* ③ 麦克风 嵌进白框右侧 */
.input-btn-mic {
