/* 🎯🎯 4. 发送按钮：指定绿 #27B465 + 黑字 🎯🎯 */
.send-btn-custom {
    order: 6 !important;
    padding: 5px 12px !important;
    height: 30px !important;
    min-width: 54px !important;
    border-radius: 5px !important;
    margin-left: 6px !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;

    /* 🎯 注入指定绿质感 */
    background: linear-gradient(to bottom, #2ec972 0%, #27B465 100%) !important;
    border: 1px solid #1f9351 !important;
    box-shadow: inset 0 1px 0 rgba(255,255,255,0.2), 0 1px 2px rgba(0,0,0,0.3) !important;
    color: #1a1a1a !important; /* 🎯 黑色字 */
